insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('f1e798d2-97e3-4a02-aa7b-053261991558', 'N5', 'Câu hỏi thân mật trong hội thoại（thể ngắn + の）', 'Cách hỏi thân mật, suồng sã hơn trong hội thoại đời thường, dùng thể ngắn (có thể thêm の để nhấn mạnh)', 'Thêm の vào cuối thể ngắn để nhấn mạnh câu hỏi, giọng thân mật hơn', '① Động từ: 行く?／行くの?；行かない?／行かないの?；行きたい?／行きたいの?；行った?／行ったの?
